import{_ as o,r as e,o as i,c as r,e as n,a as p,s as c}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Permissions - October CMS - 4.x","titleTemplate":false,"description":"Learn how to control permissions in the backend panel.","frontmatter":{"subtitle":"Learn how to control permissions in the backend panel."},"headers":[{"level":2,"title":"Permission Codes","slug":"permission-codes","link":"#permission-codes","children":[{"level":3,"title":"Nested Permissions","slug":"nested-permissions","link":"#nested-permissions","children":[]}]},{"level":2,"title":"Access Levels","slug":"access-levels","link":"#access-levels","children":[{"level":3,"title":"Super Users","slug":"super-users","link":"#super-users","children":[]},{"level":3,"title":"Roles","slug":"roles","link":"#roles","children":[]},{"level":3,"title":"Role Hierarchy","slug":"role-hierarchy","link":"#role-hierarchy","children":[]}]},{"level":2,"title":"Registering Permissions","slug":"registering-permissions","link":"#registering-permissions","children":[]},{"level":2,"title":"Restricting Access to Backend Pages","slug":"restricting-access-to-backend-pages","link":"#restricting-access-to-backend-pages","children":[]},{"level":2,"title":"Restricting Access to Features","slug":"restricting-access-to-features","link":"#restricting-access-to-features","children":[]}],"relativePath":"4.x/extend/backend/permissions.md","filePath":"4.x/extend/backend/permissions.md"}'),l={name:"4.x/extend/backend/permissions.md"};function u(d,s,g,h,k,m){const a=e("pre-heading"),t=e("post-heading");return i(),r("div",null,[n(a),s[0]||(s[0]=p("h1",null,"Permissions",-1)),n(t),s[1]||(s[1]=c(`<p>Permissions allow users to have specific privileges and functions in the backend panel. An example might be the ability to create or delete a record, or view the server logs. These permissions are based on the role assigned and can be granted on a per-user basis.</p><h2 id="permission-codes"><a href="#permission-codes" class="header-anchor">#</a> Permission Codes</h2><p>Permissions codes define a single permission and are string keys that use a &quot;dot&quot; notation, for example, <code>some.area.permission_name</code>. These permissions are granted to users by either direct assignment or by inheritance through their role.</p><p>When checking if a user has a specific permission, the permission for that user&#39;s role are inherited and then overridden by any permissions applied directly to that user. For example:</p><ul><li>If user <strong>Bob</strong> has role called <strong>Genius</strong>; and</li><li>Role <strong>Genius</strong> has the <code>eat_cake</code> permission; but</li><li><strong>Bob</strong> has the <code>eat_cake</code> permission specifically set to deny; then</li><li><strong>Bob</strong> will not get to <code>eat_cake</code>.</li></ul><p>However:</p><ul><li>If <strong>Bob</strong> has the permission <code>eat_vegetables</code> assigned directly to him, but;</li><li>The <strong>Genius</strong> role does not, then;</li><li><strong>Bob</strong> still gets to <code>eat_vegetables</code>.</li></ul><h3 id="nested-permissions"><a href="#nested-permissions" class="header-anchor">#</a> Nested Permissions</h3><p>Permission codes support a nested structure to provide a cleaner interface when selecting permissions. To nest a permission code the &quot;dot&quot; value must be a direct descendant of its parent and unlimited nesting is supported.</p><p>In the following example, the <code>manage_entries</code> permission must be granted for the <code>manage_entries.create</code> and <code>manage_entries.publish</code> codes to become available. Visually it is represented like this:</p><pre class="dir-container"><code><p>├── manage_entries
|   ├── manage_entries.create
|   └── manage_entries.publish
└── delete_entries</p>
</code></pre><h2 id="access-levels"><a href="#access-levels" class="header-anchor">#</a> Access Levels</h2><p>Access to all parts of an October CMS instance is controlled by the permissions system. The <code>BackendAuth::userHasAccess</code> method is a quick way to check if the current user is logged in and has permission to a specific area.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns true if the user has permission</span>
<span class="token variable">$permissionGranted</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;utilities.logs&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="super-users"><a href="#super-users" class="header-anchor">#</a> Super Users</h3><p>Administrators can be granted a special flag called a &quot;super user&quot; that allows access to all areas. When granted, the permission system is bypassed with access to all areas. Super users are not visible to other regular administrators.</p><div class="custom-block warning"><p>Any super user can create and remove other super users, so it should only be granted to the highest level administrator or owner of the application.</p></div><h3 id="roles"><a href="#roles" class="header-anchor">#</a> Roles</h3><p>Roles use the <code>Backend\\Models\\UserRole</code> model and are groupings of permissions with a name and description used to identify the role. An administrator can only have one role assigned to them at once.</p><p>October CMS ships with two default system roles called <code>developer</code> and <code>publisher</code>. Any number of custom roles with their own combinations of permissions can be created and applied to users.</p><div class="custom-block tip"><p>System roles cannot change their permissions however they can be deleted if not required.</p></div><h3 id="role-hierarchy"><a href="#role-hierarchy" class="header-anchor">#</a> Role Hierarchy</h3><p>Each role is assigned a ranked position in the backend panel, represented as the <code>sort_order</code> column in the database. This allows a basic organisational structure to be established where users can only manage roles lower than their own role.</p><p>In the following example, the <strong>Senior Editor</strong> can manage all the users, outranking <strong>Staff Writer</strong> and <strong>Fact Checker</strong> roles. Whereas, the <strong>Fact Checker</strong> role cannot see users or manage permissions above them, in the <strong>Staff Writer</strong> and <strong>Senior Editor</strong> roles.</p><ul><li>Senior Editor</li><li>Staff Writer</li><li>Fact Checker</li></ul><p>If the <strong>Manage Admins → Manage Roles</strong> permission is granted, users can manage their own users, permissions and roles existing below their current role.</p><h2 id="registering-permissions"><a href="#registering-permissions" class="header-anchor">#</a> Registering Permissions</h2><p>Plugins can register backend user permissions by overriding the <code>registerPermissions</code> method inside the <a href="./../extending.html">plugin registration file</a>. The permissions are defined as an array with keys corresponding the permission keys and values corresponding the permission descriptions. The permission keys consist of the author name, the plugin name and the feature name. Here is an example code.</p><div class="language- extra-class"><pre class="language-text"><code>acme.blog.access_categories
</code></pre></div><p>The next example shows how to register backend permission items. Permissions are defined with a permission key and description. In the backend permission management user interface permissions are displayed as a checkbox list. Back-end controllers can use permissions defined by plugins for restricting the user access to pages or features.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage the blog posts&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may also specify a <code>roles</code> option as an array with each value as a role API code. When a role is created with this code, it becomes a system role that always grants this permission to users with that role.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage the blog categories&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;developer&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="restricting-access-to-backend-pages"><a href="#restricting-access-to-backend-pages" class="header-anchor">#</a> Restricting Access to Backend Pages</h2><p>In a backend controller class you can specify which permissions are required for access the pages provided by the controller. It&#39;s done with the <code>$requiredPermissions</code> controller&#39;s property. This property should contain an array of permission keys. If the user permissions match any permission from the list, the framework will let the user to see the controller pages.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>BackendController</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name">BackendController</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also use the <strong>asterisk</strong> symbol to indicate the &quot;all permissions&quot; condition. In the next example the controller pages are accessible for all users who has any permissions starting with the &quot;acme.blog.&quot; string:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="restricting-access-to-features"><a href="#restricting-access-to-features" class="header-anchor">#</a> Restricting Access to Features</h2><p>The backend user model has methods that allow determining whether the user has specific permissions. You can use this feature in order to limit the functionality of the backend user interface. The permission methods supported by the backend user are <code>userHasAccess</code> and <code>userHasPermission</code>. Both methods take two parameters: the permission key string (or an array of key strings) and an optional parameter indicating that all permissions listed with the first parameters are required.</p><p>The <code>userHasAccess</code> method returns <strong>true</strong> for any permission if the user is a super user. The <code>userHasPermission</code> method is more strict, only returning true if the user actually has the specified permissions either in their account or through their role. Generally, <code>userHasAccess</code> is the preferred method to use as it respects the absolute power of the super user. The following example shows how to use the methods in the controller code.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasPermission</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also use the methods in the backend views for hiding user interface elements. The next example demonstrates how you can hide a button on a <a href="./../forms/form-controller.html">backend form</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.delete_categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>oc-icon-trash-o btn-icon danger<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-load-indicator</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Deleting Category...<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Do you really want to delete this category?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div>`,44))])}const y=o(l,[["render",u]]);export{b as __pageData,y as default};
